import { execute, query } from '@/lib/db';
import { newId } from '@/lib/ids';
import { utcDayBounds } from '@/lib/time';

export interface AppointmentRow {
  id: string;
  org_id: string;
  patient_id: string;
  practitioner_id: string;
  starts_at: Date;
  ends_at: Date;
  status: 'booked' | 'cancelled' | 'completed';
  visit_reason: string | null;
  notes: string | null;
  created_by_user_id: string;
  created_at: Date;
}

export async function listForPatient(patientId: string): Promise<AppointmentRow[]> {
  return query<AppointmentRow>(
    'SELECT * FROM appointments WHERE patient_id = ? ORDER BY starts_at',
    [patientId],
  );
}

/**
 * A practitioner's appointments for one UTC day, limited to patients they still have
 * access to. Rows include the patient's name for display.
 */
export async function listForPractitionerOnDay(
  practitionerId: string,
  day: string,
): Promise<Array<AppointmentRow & { patient_first_name: string; patient_last_name: string }>> {
  const { start, end } = utcDayBounds(day);
  return query(
    `SELECT a.*, p.first_name AS patient_first_name, p.last_name AS patient_last_name
       FROM appointments a
       JOIN patients p ON p.id = a.patient_id
       JOIN care_team ct ON ct.practitioner_id = a.practitioner_id AND ct.patient_id = a.patient_id AND ct.active = 1
      WHERE a.practitioner_id = ? AND a.starts_at >= ? AND a.starts_at < ? AND a.status <> 'cancelled'
      ORDER BY a.starts_at`,
    [practitionerId, start, end],
  );
}

export async function createAppointment(input: {
  orgId: string;
  patientId: string;
  practitionerId: string;
  startsAt: Date;
  endsAt: Date;
  visitReason: string | null;
  createdByUserId: string;
}): Promise<string> {
  const id = newId('apt');
  await execute(
    `INSERT INTO appointments (id, org_id, patient_id, practitioner_id, starts_at, ends_at, status, visit_reason, created_by)
     VALUES (?, ?, ?, ?, ?, ?, 'booked', ?, ?)`,
    [id, input.orgId, input.patientId, input.practitionerId, input.startsAt, input.endsAt, input.visitReason, input.createdByUserId],
  );
  return id;
}
import { query } from '@/lib/db';

export interface NoteRow {
  id: string;
  kind: 'clinical' | 'psychotherapy';
  patient_id: string;
  practitioner_id: string;
  created_at: Date;
  body: string;
}

/** All notes for a patient, newest first, for the practitioner chart view. */
export async function listForPatient(patientId: string): Promise<NoteRow[]> {
  return query<NoteRow>(
    `SELECT id, 'clinical' AS kind, patient_id, practitioner_id, created_at, body FROM clinical_notes WHERE patient_id = ?
     UNION ALL
     SELECT id, 'psychotherapy' AS kind, patient_id, practitioner_id, created_at, body FROM psychotherapy_notes WHERE patient_id = ?
     ORDER BY created_at DESC`,
    [patientId, patientId],
  );
}
CREATE TABLE messages (
  id                 VARCHAR(32)  NOT NULL PRIMARY KEY,
  org_id             VARCHAR(32)  NOT NULL,
  sender_user_id     VARCHAR(32)  NOT NULL,
  recipient_user_id  VARCHAR(32)  NOT NULL,
  patient_id         VARCHAR(32)  NULL,
  subject            VARCHAR(200) NOT NULL,
  body               TEXT         NOT NULL,
  created_at         DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  read_at            DATETIME(3)  NULL,
  KEY idx_messages_recipient (recipient_user_id, created_at),
  CONSTRAINT fk_msg_sender FOREIGN KEY (sender_user_id) REFERENCES users(id),
  CONSTRAINT fk_msg_recipient FOREIGN KEY (recipient_user_id) REFERENCES users(id),
  CONSTRAINT fk_msg_patient FOREIGN KEY (patient_id) REFERENCES patients(id)
) ENGINE=InnoDB;

CREATE TABLE appointments (
  id                  VARCHAR(32)  NOT NULL PRIMARY KEY,
  org_id              VARCHAR(32)  NOT NULL,
  patient_id          VARCHAR(32)  NOT NULL,
  practitioner_id     VARCHAR(32)  NOT NULL,
  starts_at           DATETIME     NOT NULL,
  ends_at             DATETIME     NOT NULL,
  status              ENUM('booked','cancelled','completed') NOT NULL DEFAULT 'booked',
  visit_reason        VARCHAR(500) NULL,
  notes               TEXT         NULL,
  created_by_user_id  VARCHAR(32)  NOT NULL,
  created_at          DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  KEY idx_appt_pract_day (practitioner_id, starts_at),
  CONSTRAINT fk_appt_patient FOREIGN KEY (patient_id) REFERENCES patients(id),
  CONSTRAINT fk_appt_pract FOREIGN KEY (practitioner_id) REFERENCES practitioners(id)
) ENGINE=InnoDB;

-- General clinical record (progress notes, assessments).
CREATE TABLE clinical_notes (
  id               VARCHAR(32) NOT NULL PRIMARY KEY,
  patient_id       VARCHAR(32) NOT NULL,
  practitioner_id  VARCHAR(32) NOT NULL,
  created_at       DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  body             TEXT        NOT NULL,
  CONSTRAINT fk_cn_patient FOREIGN KEY (patient_id) REFERENCES patients(id)
) ENGINE=InnoDB;

-- Psychotherapy notes are kept apart from the general record (see docs/sources.md).
CREATE TABLE psychotherapy_notes (
  id               VARCHAR(32) NOT NULL PRIMARY KEY,
  patient_id       VARCHAR(32) NOT NULL,
  practitioner_id  VARCHAR(32) NOT NULL,
  created_at       DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  body             TEXT        NOT NULL,
  CONSTRAINT fk_pn_patient FOREIGN KEY (patient_id) REFERENCES patients(id)
) ENGINE=InnoDB;

import { execute } from './db';
import type { CurrentUser } from './auth';

/** Records who did what to which record. Store ids only, never content. */
export async function audit(user: CurrentUser, action: string, targetType: string, targetId: string): Promise<void> {
  await execute(
    'INSERT INTO audit_log (user_id, action, target_type, target_id) VALUES (?, ?, ?, ?)',
    [user.id, action, targetType, targetId],
  );
}
